<?php
require_once __DIR__.'/../config/koneksi.php';require_once __DIR__.'/../config/functions.php';require_login('pekerja');
$user=current_user();$stmt=$pdo->prepare("SELECT l.*,lo.judul,lo.lokasi,lo.kategori,u.nama penyedia FROM lamaran l JOIN lowongan lo ON lo.id=l.lowongan_id JOIN users u ON u.id=lo.penyedia_id WHERE l.pekerja_id=:user ORDER BY l.tanggal_lamar DESC");$stmt->execute(['user'=>(int)$user['id']]);$items=$stmt->fetchAll();
$success=flash('success');
$pageTitle='Lamaran Saya';require __DIR__.'/../includes/header.php';
?>
<main class="dashboard-main"><p class="eyebrow">Pekerja / talenta</p><h1 class="dashboard-title">Lamaran saya</h1><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif?><section class="dashboard-panel"><h2>Riwayat lamaran</h2><?php if($items):?><div class="table-wrapper" role="region" aria-label="Daftar lamaran" tabindex="0"><table class="dashboard-table"><thead><tr><th>Lowongan</th><th>Penyedia</th><th>Tanggal</th><th>Status</th></tr></thead><tbody><?php foreach($items as $x):?><tr><th><?=e($x['judul'])?><small><?=e($x['kategori'])?> · <?=e($x['lokasi'])?></small></th><td><?=e($x['penyedia'])?></td><td><?=e(date('d M Y',strtotime($x['tanggal_lamar'])))?></td><td><span class="<?=$x['status']==='Diterima'?'badge-green':($x['status']==='Ditolak'?'badge-amber':'badge-green')?>"><?=e($x['status'])?></span></td></tr><?php endforeach?></tbody></table></div><?php else:?><div class="empty-state">Belum ada lamaran. Temukan lowongan yang sesuai di rekomendasi pekerjaan.</div><?php endif?></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
